item.text:
{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Missing information does not establish whether repeated testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "70% in one reported run",
          "reason": "One reported score does not establish variation across runs."
        }
      ],
      "instrument_review": "MESA 14 and 16 distinguish evidence that repeated testing occurred from evidence about score variation. Neither is supplied."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "ran the evaluation exactly once",
          "reason": "A single run cannot establish stability; it also does not demonstrate instability."
        }
      ],
      "instrument_review": "MESA 14 would record that repeated testing did not occur. Under MESA 16, variation across runs remains unknown."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "Repeated testing under the same conditions is explicitly reported."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's stability threshold of at most two percentage points."
        }
      ],
      "instrument_review": "MESA 14 supports that repeated testing occurred. MESA 16 supports stability under the stated definition for these runs and conditions."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "Repeated testing occurred regardless of whether its findings were favourable."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed range exceeds the stated stability threshold of two percentage points."
        }
      ],
      "instrument_review": "MESA 14 supports that testing occurred, while MESA 16 provides evidence against stability under the report's definition."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation instructions do not establish that repeated testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "No findings establish score variation across runs."
        }
      ],
      "instrument_review": "The installation instructions concern MESA 22's reproducibility materials. They do not resolve the missing evidence for MESA 14 or 16."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "A achieved the higher result on the evaluated grid puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The findings do not establish comparative general intelligence across domains."
        }
      ],
      "instrument_review": "MESA 2, 20 and 25 support interpretation within the stated grid-puzzle use. Broader performance claims lack evidence."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "A performed better on the evaluated puzzles under the stated conditions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "Declaring a broad intended use does not supply evidence of ability across domains."
        }
      ],
      "instrument_review": "MESA 9, 20 and 25 expose a gap between the narrow evidence and the intended general-intelligence selection. The narrow comparison remains supported."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial scores alone provide no demonstrated link to improved real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial, blinded correctness checks and reported difference interval support better correctness with A in the studied setting."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Improved correctness does not establish an unmeasured safety benefit."
        }
      ],
      "instrument_review": "MESA 20 gains relevant evidence from the later workshop trial, and MESA 16 gains a reported uncertainty interval. Under MESA 25, conclusions should remain limited to correctness in the studied workshop and conditions."
    }
  ],
  "closing_note": "No instructions were unclear. Labels classify the probe statements, not MESA ratings; missing evidence was not treated as contradiction."
}
